{"results": [{"id": "hp_doc_eb9b27fe0ad669b81dfc0df2e9aedc8828e2118c77bd7b45f9b04e2652833505", "title": "Napeague State Park", "text": "Napeague State Park is a 1364 acre state park in the town of East Hampton in Suffolk County, New York. The largely undeveloped park stretches across the entire narrow width of the South Fork of Long Island from the Atlantic Ocean to Gardiners Bay and Block Island Sound. The park is located on either side of the Montauk Highway (New York Route 27) on the \"Napeague Stretch\" between Amagansett and Montauk. The hamlet of Napeague is located on the park's edge.", "score": 33.4146}, {"id": "hp_doc_06e72ac8b78513223b54efe4f291f6dd9e7db0655179306e78bb1699abef8e35", "title": "Shadmoor State Park", "text": "Shadmoor State Park is a 99 acre state park located in Suffolk County, New York in the United States. Created in 2000, the park is located in Town of East Hampton on the South Fork of Long Island, 1/4 mi east of the hamlet of Montauk.", "score": 30.2251}, {"id": "hp_doc_d1a501f319dc80445dea14db197e6abc9f1ecf5dae7264239738a6937bb29f87", "title": "Montauk Point State Park", "text": "Montauk Point State Park is a 862 acre state park located in the hamlet of Montauk, at the eastern tip of Long Island in the Town of East Hampton, Suffolk County, New York. Montauk Point is the easternmost extremity of the South Fork of Long Island, and thus also of New York State.", "score": 27.8835}], "remaining_searches": 2}
